package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by category and price range
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Basic input length check
	if len(category) > 100 || len(minPrice) > 20 || len(maxPrice) > 20 {
		http.Error(w, "input too long", http.StatusBadRequest)
		return
	}

	// Build query - using parameterized query for price but string formatting for category
	// Developer note: category is from a controlled dropdown on frontend
	var query string
	if sortBy == "price_asc" {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price BETWEEN $1 AND $2 ORDER BY price ASC LIMIT 50",
			category,
		)
	} else if sortBy == "price_desc" {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price BETWEEN $1 AND $2 ORDER BY price DESC LIMIT 50",
			category,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price BETWEEN $1 AND $2 ORDER BY name LIMIT 50",
			category,
		)
	}

	rows, err := db.Query(query, minPrice, maxPrice)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", id, name, price))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

// healthHandler for ALB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
